/bin/bash -lc "python - <<'PY'
import json
x=json.load(open('input.json'));p=x['proposal'];b=x['currentCanonicalBaseline']
def diff(a,c,path=''):
 if type(a)"'!=type(c): return [path]
 if isinstance(a,dict):
  z=[]
  for k in sorted(set(a)|set(c)):
   if k not in a or k not in c:z.append(path+'"'.'+k)
   else:z+=diff(a[k],c[k],path+'.'+k)
  return z
 if isinstance(a,list):
  if len(a)"'!=len(c):return [path]
  return sum((diff(v,w,path+'"'.'+str(i)) for i,(v,w) in enumerate(zip(a,c))),[])
 return [] if a==c else [path]
print('INDEPENDENT DIFF',*diff(b,p),sep='\\n')
print('SCHEMA',json.dumps(json.load(open('output.schema.json')),indent=2))
PY"

